"""AUTO-GENERATED rule: attacking_axis_feeder.

Generated by scripts/scaffold_rule.py from template 'axis_feeder' on
qualifier 'attacking'. Surfaces tier-ranked payoff cards for any
commander whose port carries the qualifier on a non-Self scope.
Mirrors the shape of ``modified_axis_feeder`` / ``counter_axis_feeder``
in ``utility.py``.

Auditor context at generation time:
- Reach: 17 commanders carrying this signature
- Currently uncovered: 17
"""

from __future__ import annotations

import sqlite3

from ..core import PortComplement, PortRow

#: The qualifier this rule fires on. Stored as a constant so the gate
#: predicate and helper share the same anchor.
_QUALIFIER = "attacking"


def _is_self_qualified(filter_or_clause: str) -> bool:
    """True iff first OR-alt of the filter carries a Self token.

    Mirrors ``_is_self_qualified`` in utility.py — commander-level
    "this commander is X" conditions don't promote to per-card payoff
    axes.
    """
    first_alt = filter_or_clause.split(",")[0]
    alt_tokens = first_alt.replace("+", ".").split(".")
    return any(tok.lstrip("!").strip() == "Self" for tok in alt_tokens)


def _has_qualifier_token(vf: str, qualifier: str) -> bool:
    """True iff ``qualifier`` appears as a standalone token in ``vf``.

    Forge filters use ``+`` and ``.`` as token separators. A naive
    substring test would conflate ``attacking`` with ``attackingYou``
    (a different token meaning "creatures attacking you"), causing
    the gate to fire on defensive commanders like Lulu, Stern Guardian.
    Tokenise on those separators and check for an exact match (with
    optional negation prefix stripped).
    """
    for alt in vf.split(","):
        for tok in alt.replace("+", ".").split("."):
            if tok.lstrip("!").strip() == qualifier:
                return True
    return False


def _attacking_axis_feeder_gate(port: PortRow) -> bool:
    """True iff ``port``'s valid_filter carries the qualifier as a
    standalone token on a YouCtrl-or-unscoped axis.

    Rejects:
    - Self-anchored (commander-level conditions, not payoff axes)
    - OppCtrl scope (defensive utilities like Catti-brie's anti-attacker
      damage are NOT attack-axis payoffs — they want pillowfort, not
      pump)
    """
    if (port.get("port_type") or "").strip() not in (
        "trigger",
        "scales_with",
        "static",
        "effect",
        "cost",
        "replacement",
    ):
        return False
    vf = (port.get("valid_filter") or "").strip()
    if not vf or not _has_qualifier_token(vf, _QUALIFIER):
        return False
    if _is_self_qualified(vf):
        return False
    # Reject opponent-scoped filters: defensive payoffs masquerading
    # as attacking-axis ports.
    return "OppCtrl" not in vf and "OppOwn" not in vf


def _find_attacking_axis_feeder(
    conn: sqlite3.Connection,
    cmdr_ports: list[PortRow],
    cmdr_set: set[str],
) -> list[PortComplement]:
    """Return tier-ranked payoff cards for the qualifier axis.

    Activation: commander has any port whose ``valid_filter`` mentions
    the qualifier on a non-Self scope. Output is deduped — a card
    matching multiple tiers gets exactly one complement, with the
    highest-priority tier's ``cand_event`` attached.
    """
    if not any(_attacking_axis_feeder_gate(p) for p in cmdr_ports):
        return []

    # static.Continuous Affected attacking creatures + AddPower/AddKeyword (~38 cards)
    attacking_anthem_set: set[str] = {
        row["card_name"]
        for row in conn.execute(
            "SELECT DISTINCT card_name FROM card_ports WHERE port_type='static' AND event_class='Continuous' AND raw_line LIKE '%attacking%' AND (raw_line LIKE '%AddPower%' OR raw_line LIKE '%AddKeyword%')"
        )
    }

    # effect.PumpAll on attacking creatures, e.g. Overrun (~73 cards)
    attacking_mass_pump_set: set[str] = {
        row["card_name"]
        for row in conn.execute(
            "SELECT DISTINCT card_name FROM card_ports WHERE port_type='effect' AND event_class='PumpAll' AND valid_filter LIKE '%attacking%'"
        )
    }

    # scales_with.Valid attacking — peer commanders on the same axis
    attacking_peer_scaler_set: set[str] = {
        row["card_name"]
        for row in conn.execute(
            "SELECT DISTINCT card_name FROM card_ports WHERE port_type='scales_with' AND event_class='Valid' AND valid_filter LIKE '%attacking%'"
        )
    }

    tier_priority = (
        ("attacking_anthem", attacking_anthem_set),
        ("attacking_mass_pump", attacking_mass_pump_set),
        ("attacking_peer_scaler", attacking_peer_scaler_set),
    )
    seen: set[str] = set()
    results: list[PortComplement] = []
    for cand_event, candidates in tier_priority:
        for name in candidates:
            if name in cmdr_set or name in seen:
                continue
            seen.add(name)
            results.append(
                PortComplement(
                    rule_id="attacking_axis_feeder",
                    direction="synergy",
                    candidate=name,
                    cmdr_event=f"{_QUALIFIER}_axis",
                    cand_event=cand_event,
                )
            )
    return results
